--- index.html
+++ index.html
@@ -94,8 +94,9 @@
 function showToast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
 function burst(x,y,text){const el=document.createElement('span');el.className='burst';el.textContent=text;el.style.left=x+'px';el.style.top=y+'px';$('corePanel').appendChild(el);setTimeout(()=>el.remove(),850)}
 function tap(event){const amount=clickPower();gain(amount);const rect=$('corePanel').getBoundingClientRect();const x=event&&event.clientX?event.clientX-rect.left:rect.width/2;const y=event&&event.clientY?event.clientY-rect.top:rect.height/2;burst(x,y,'+'+fmt(amount)+' ✧');const btn=$('coreButton');btn.classList.add('pressed');setTimeout(()=>btn.classList.remove('pressed'),100);}
 $('coreButton').addEventListener('pointerdown',e=>{e.preventDefault();tap(e)});
+$('coreButton').addEventListener('click',e=>{if(e.detail===0)tap()});
 document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&!['BUTTON'].includes(document.activeElement.tagName)&&!$('rebirthModal').classList.contains('open')){e.preventDefault();tap()}});
 function buy(type){const cost=type==='click'?clickPrice():type==='drone'?dronePrice():ampPrice();if(state.energy<cost)return;state.energy-=cost;if(type==='click')state.clickLevel++;if(type==='drone')state.drones++;if(type==='amp')state.amps++;render();save()}
 $('buyClick').addEventListener('click',()=>buy('click'));$('buyAuto').addEventListener('click',()=>buy('drone'));$('buyAmplifier').addEventListener('click',()=>buy('amp'));
 $('rebirthButton').addEventListener('click',()=>{if(state.total<10000)return;$('modalReward').textContent='Your multiplier will rise to ×'+(multiplier()+.5).toFixed(1);$('rebirthModal').classList.add('open')});
